import json, freya
from pathlib import Path
OUT = Path('experiments/cursor-statement/out/run-2')
slot = json.loads((OUT/'freya-slot.json').read_text())['cursor-bank-2']
agent_id = slot['agent_id']
# quick personas for happy + side-exit
personas = [
  {
    "name": "run2-tek-kart-borc",
    "description": "Tek kartı olan müşteri, borç dinler, teşekkür eder, işlemi bitirir.",
    "prompt": "Sen Freya Bank müşterisisin. Türkçe konuş, sizli. Kart borcunu öğrenmek istiyorsun. Tek kartın var. Borcu dinledikten sonra başka bir şey istemiyorsun, teşekkür edip kapat. Ödeme yapmak veya temsilci istemiyorsun.",
    "language": "tr",
  },
  {
    "name": "run2-temsilci",
    "description": "Kart seçiminde müşteri temsilcisi ister.",
    "prompt": "Sen Freya Bank müşterisisin. Türkçe konuş. Birden fazla kartın olabilir. Asistan kart sorduğunda hemen müşteri temsilcisiyle görüşmek istediğini söyle. Başka bir şey söyleme.",
    "language": "tr",
  },
]
try:
    created = freya.create_personas(personas)
    # API shape varies
    items = created.get('personas') or created.get('items') or created
    if isinstance(items, dict):
        items = items.get('personas') or list(items.values())
    print('personas created count', len(items) if isinstance(items, list) else type(items))
    ids = []
    if isinstance(items, list):
        for p in items:
            if isinstance(p, dict) and p.get('id'):
                ids.append((p.get('name'), p['id']))
    print('ids', ids)
    (OUT/'personas.json').write_text(json.dumps(created, ensure_ascii=False, indent=1)[:5000], encoding='utf-8')
except Exception as e:
    print('persona error', type(e).__name__, str(e)[:500])
    ids = []

# if we have ids, run a short sim
if len(ids) >= 1:
    vmap = {}
    for name, pid in ids[:2]:
        vmap[pid] = {"customerNumber": "90000001", "now": "2026-10-11T12:00:00"}
    try:
        sim_id, it_id, status = freya.run_simulation(agent_id, 'cursor-bank-2-smoke', vmap, max_seconds=180, concurrency=2)
        print('sim', sim_id, 'iter', it_id, 'status', status)
        it = freya.get_iteration(sim_id, it_id)
        runs = it.get('runs') or []
        summary=[]
        for r in runs:
            summary.append({
                'persona': r.get('personaName') or r.get('personaId'),
                'outcome': r.get('outcome') or r.get('status'),
                'callId': r.get('callId') or r.get('id'),
            })
        print('runs', summary)
        (OUT/'sim-smoke.json').write_text(json.dumps({'sim_id': sim_id, 'iteration_id': it_id, 'status': status, 'runs': summary}, indent=1), encoding='utf-8')
    except Exception as e:
        print('sim error', type(e).__name__, str(e)[:800])

# sync rules to parent out/
import shutil
shutil.copy2(OUT/'rules.json', 'experiments/cursor-statement/out/rules.json')
print('done')
# list out files
for p in sorted(OUT.iterdir()):
    print(p.name, p.stat().st_size)
PY

